// Generated by scripts/optimize-local-images.mjs from logo_nt.webp (626×633
// original, drawn at only 28–36px). The browser picks the smallest copy that
// is still sharp at the current screen density.
import logo56 from "@/assets/responsive/logo_nt-56w.webp";
import logo84 from "@/assets/responsive/logo_nt-84w.webp";
import logo112 from "@/assets/responsive/logo_nt-112w.webp";
import logo144 from "@/assets/responsive/logo_nt-144w.webp";
import { useSiteSettings } from "@/site/context/SiteSettingsProvider";

const LOGO_SRCSET = `${logo56} 56w, ${logo84} 84w, ${logo112} 112w, ${logo144} 144w`;

// `sizes` is how wide the logo is drawn where it is used (28px / 32px / 36px).
function SiteLogo({ sizes }) {
  const settings = useSiteSettings();
  // The logo is the only content of its link, so its alt text IS the link's
  // accessible name — "Logo" told screen readers nothing about where it goes.
  const logoAlt = settings?.agency_name || "Logo";

  return (
    <img
      className="h-full w-auto"
      src={logo112}
      srcSet={LOGO_SRCSET}
      sizes={sizes}
      width="626"
      height="633"
      alt={logoAlt}
    />
  );
}

export default SiteLogo;
